const fs = require('fs');

// Находим самый свежий endpoints.json
const files = fs.readdirSync('/results')
  .filter(f => f.endsWith('_endpoints.json'))
  .map(f => ({
    name: f,
    path: `/results/${f}`,
    mtime: fs.statSync(`/results/${f}`).mtime.getTime(),
  }))
  .sort((a, b) => b.mtime - a.mtime);

if (files.length === 0) {
  throw new Error('No endpoints.json found in /results/');
}

console.log('Reading:', files[0].path);

const discovery = JSON.parse(fs.readFileSync(files[0].path, 'utf8'));
console.log(`Loaded: ${discovery.endpointCount} endpoints, vuln=${discovery.vulnType}, runId=${discovery.runId}`);

return [{ json: discovery }];

const cfg = $input.first().json;
const fs = require('fs');

const VULN_FILTERS = {
  sqli:      /(sqli|login|user|search|api|ping|transfer|contact)/i,
  xss:       /(xss|search|reflected|stored|dom|contact|comment)/i,
  cmd:       /(rce|ping|eval)/i,
  ptrav:     /(ptrav|read|download|file|page)/i,
  ssti:      /(ssti|template|render)/i,
  lfi:       /(lfi|file|page|read|include)/i,
  redirect:  /(redirect|redir|open_redirect)/i,
  xxe:       /(xxe|parse|xml|upload)/i,
  special:   /./,
  universal: /./,
};

const filter = VULN_FILTERS[cfg.vulnType] || /./;

const candidates = (cfg.endpoints || [])
  .filter(ep => filter.test(ep))
  .filter(ep => !ep.includes('FUZZ'))
  .slice(0, 5);

console.log(`Prepare Arjun: ${candidates.length} candidates from ${cfg.endpoints.length} total`);

// ПРОПУСКАЕМ ARJUN, ЕСЛИ В ФОРМЕ НЕ СТОИТ ГАЛОЧКА ИЛИ НЕТ КАНДИДАТОВ
if (!cfg.useArjun || candidates.length === 0) {
  const emptyResult = {
    runId: cfg.runId,
    target: cfg.target,
    vulnType: cfg.vulnType,
    arjunParams: {},
    arjunSkipped: true,
    timestamp: new Date().toISOString(),
  };
  fs.writeFileSync(cfg.arjunFile, JSON.stringify(emptyResult, null, 2));
  console.log(`Arjun skipped. useArjun=${cfg.useArjun}, candidates=${candidates.length}`);

  return [{ json: { ...cfg, arjunSkipped: true, arjunParams: {} } }];
}

return candidates.map((ep, i) => ({
  json: {
    ...cfg,
    arjunEndpoint: ep,
    arjunIndex: i,
  }
}));

const fs = require('fs');

const cfg = $('Read Endpoints File').first().json;

const items = $input.all();

// Если Arjun был пропущен
if (cfg.arjunSkipped) {
  console.log('Arjun skipped — nothing to parse');
  return [{ json: { ...cfg, arjunParams: {} } }];
}

const arjunParams = {};
let parsedCount = 0;
let emptyCount = 0;

for (const item of items) {
  const d = item.json;
  const stdout = (d.stdout || '').trim();

  if (!stdout) {
    emptyCount++;
    continue;
  }

  // Ищем JSON внутри stdout
  const jsonMatch = stdout.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    console.log(`No JSON in stdout: ${stdout.slice(0, 100)}`);
    continue;
  }

  try {
    const data = JSON.parse(jsonMatch[0]);

    for (const [url, val] of Object.entries(data)) {
      if (Array.isArray(val)) {
        arjunParams[url] = val.map(p => typeof p === 'string' ? p : (p.name || ''));
      } else if (val && typeof val === 'object') {
        arjunParams[url] = Object.keys(val);
      }
      parsedCount++;
    }
  } catch (e) {
    console.error('Parse error:', e.message);
  }
}

console.log(`Arjun parsed: ${parsedCount} endpoints, ${emptyCount} empty responses`);
console.log(`Total params: ${Object.values(arjunParams).flat().length}`);


return [{ json: { ...cfg, arjunParams } }];

const cfg = $input.first().json;
const fs = require('fs');

const result = {
  runId: cfg.runId,
  target: cfg.target,
  vulnType: cfg.vulnType,
  arjunParams: cfg.arjunParams || {},
  arjunSkipped: !!cfg.arjunSkipped,
  timestamp: new Date().toISOString(),

  // Пути ко всем дальнейшим файлам
  endpointsFile:     cfg.endpointsFile,
  dictResultsFile:   cfg.dictResultsFile,
  schemaResultsFile: cfg.schemaResultsFile,
  reportFile:        cfg.reportFile,
  configFile:        cfg.configFile,
  baselineFile:      cfg.baselineFile,
};

fs.writeFileSync(cfg.arjunFile, JSON.stringify(result, null, 2));

const totalParams = Object.values(result.arjunParams).flat().length;
console.log(`Workflow 2 DONE. Endpoints with params: ${Object.keys(result.arjunParams).length}, total params: ${totalParams}`);
console.log(`File: ${cfg.arjunFile}`);

return [{ json: result }];
